#ifndef __MEM_INIT_H__
#define __MEM_INIT_H__

#include "image.hpp"
#include "fib.hpp"
#include <cstdint>

class ScampTrieDynamic;

// Typed memory exporter: turns a complete live FIB into a detached compact
// image. The result is self contained (fronts, cells, banks, dictionaries)
// and never aliases live storage, so later puts cannot change a snapshot.
class MemInit {
public:
    explicit MemInit(ScampTrieDynamic* trie);
    ~MemInit();

    ImageData capture();
};

// Build a compact image for an arbitrary FIB. Exposed for reuse and tests.
ImageData build_image(const Fib& fib);

#endif // __MEM_INIT_H__
